public class SuffixArray {
    public static int[] buildSA(String s) {
        int n = s.length();
        Integer[] sa = new Integer[n];
        for (int i=0;i<n;i++) sa[i]=i;
        int[] rank = new int[n], tmp = new int[n];
        for (int i=0;i<n;i++) rank[i]=s.charAt(i);
        for (int gap=1;gap<n;gap*=2) {
            final int[] r=rank, g=gap;
            java.util.Arrays.sort(sa,(a,b)->{
                if(r[a]!=r[b]) return r[a]-r[b];
                int ra=a+g<n?r[a+g]:-1, rb=b+g<n?r[b+g]:-1;
                return ra-rb;
            });
            tmp[sa[0]]=0;
            for(int i=1;i<n;i++){
                tmp[sa[i]]=tmp[sa[i-1]];
                int pa=sa[i-1],pb=sa[i];
                if(r[pa]!=r[pb]||(pa+g<n?r[pa+g]:-1)!=(pb+g<n?r[pb+g]:-1)) tmp[sa[i]]++;
            }
            System.arraycopy(tmp,0,rank,0,n);
        }
        int[] result=new int[n]; for(int i=0;i<n;i++) result[i]=sa[i]; return result;
    }
}

